{
  "category_edits": [
    {
      "category": "interest_aggregation",
      "rationale": "Blend each causal encoder state with a padding-masked, exponentially recency-weighted mean of states through that position: 0.8 * current + 0.2 * pooled, with decay timescale 10. This may stabilize sparse interests while preserving recent intent. Training and prediction share log2feats; the embedded predictor already imports the updated SASRec class. Backbone, scoring, loss, optimizer, routing and hyperparameters remain unchanged.",
      "edits": [
        {
          "find": "        return self.last_layernorm(seq_emb)",
          "replace": "        states = self.last_layernorm(seq_emb)\n        positions = torch.arange(M, device=seq.device, dtype=states.dtype)\n        age = positions[:, None] - positions[None, :]\n        weights = torch.exp(-age.clamp_min(0) / 10.0) * (age >= 0).to(states.dtype)\n        valid = (~timeline_mask).to(states.dtype)\n        weighted_sum = torch.matmul(weights, states * valid.unsqueeze(-1))\n        weight_sum = torch.matmul(valid, weights.transpose(0, 1))\n        pooled = weighted_sum / weight_sum.clamp_min(1.0).unsqueeze(-1)\n        return 0.8 * states + 0.2 * pooled"
        }
      ]
    }
  ],
  "change_summary": "Add causal recency-weighted interest aggregation consistently across position-wise training and inference, retaining one SASRec model per dataset."
}
